import{_ as s,o,c as t,a3 as i,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/vorbereitung/kataloge-zeugnisvorlagen-zuordnen-1.png",l="/bilder/vorbereitung/kataloge-zeugnisvorlagen-zuordnen-2-zeugniskonfigurationpng.png",f=JSON.parse('{"title":"Zeugnisvorlagen für den Gruppendruck zuordnen","description":"","frontmatter":{"title":"Zeugnisvorlagen für den Gruppendruck zuordnen","source_pageid":932,"source_revision":6867},"headers":[],"relativePath":"zeugnisse/vorbereitung/zeugnisvorlagen-zuordnen-schulbezogene-kataloge.md","filePath":"zeugnisse/vorbereitung/zeugnisvorlagen-zuordnen-schulbezogene-kataloge.md"}'),u={name:"zeugnisse/vorbereitung/zeugnisvorlagen-zuordnen-schulbezogene-kataloge.md"};function g(d,r,c,p,h,m){return o(),t("div",null,[...r[0]||(r[0]=[i('<h1 id="zeugnisvorlagen-fur-den-gruppendruck-zuordnen" tabindex="-1">Zeugnisvorlagen für den Gruppendruck zuordnen <a class="header-anchor" href="#zeugnisvorlagen-fur-den-gruppendruck-zuordnen" aria-label="Permalink to &quot;Zeugnisvorlagen für den Gruppendruck zuordnen&quot;">​</a></h1><p>Verknüpfen Sie Zeugnisreports mit Jahrgang, Zeugnisart und gegebenenfalls Abschluss. Diese Zuordnungen erleichtern anschließend den gemeinsamen Druck.</p><p><a href="/bilder/vorbereitung/kataloge-zeugnisvorlagen-zuordnen-1.png"><img src="'+a+'" alt="Zuordnen von Zeugnisvorlagen." loading="lazy"></a></p><p><em>Zuordnen von Zeugnisvorlagen.</em></p><p>Über <em>Kataloge ➜ Schulbezogene Kataloge</em> können in SchILD-NRW 3 Reports als <strong>Zeugnisvorlagen</strong> zugeordnet werden.</p><p>Diese lassen sich anschließend deutlich einfacher drucken, da die einzelnen Reports nicht mehr im Report-Explorer gesucht werden müssen.</p><p>Der Druck erfolgt anschließend über den Gruppenprozess <strong>Zugeordnete Zeugnisformulare drucken</strong>.</p><p><a href="/bilder/vorbereitung/kataloge-zeugnisvorlagen-zuordnen-2-zeugniskonfigurationpng.png"><img src="'+l+'" alt="Konfigurieren Sie ein Zeugnis und wählen Sie die passende Vorlage aus." loading="lazy"></a></p><p><em>Konfigurieren Sie ein Zeugnis und wählen Sie die passende Vorlage aus.</em></p><p>Klicken Sie auf das Symbol <strong>+</strong>, um einen neuen Eintrag anzulegen. Geben Sie anschließend direkt eine aussagekräftige <strong>Beschreibung</strong> ein.</p>',10),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Es ist empfehlenswert, sich bei der Benennung an den Dateinamen des jeweils zugeordneten Zeugnis-Reports zu orientieren.")],-1),i("<p>Tragen Sie danach die weiteren Angaben passend ein:</p><ul><li><strong>Zeugnisart</strong></li><li><strong>Jahrgang</strong></li><li>gegebenenfalls <strong>Abschlussart</strong> und <strong>Abschluss</strong></li></ul><p>Bei einem Jahrgang ohne Abschluss wird in der <em>Abschlussart</em> der Wert <em>Jahrgang ohne Abschluss</em> eingetragen; das Feld <em>Abschluss</em> bleibt in diesem Fall leer.</p><p>Fügen Sie zusätzlich eine <strong>Gruppe</strong> hinzu. Dadurch lassen sich die Vorlagen besser unterscheiden. Im Gruppenprozess <strong>Zugeordnete Zeugnisformulare drucken</strong> kann später gezielt nach dieser Gruppe gefiltert werden.</p><p>Wählen Sie abschließend den passenden Report als <strong>Zeugnisvorlage</strong> aus. Die aktuellen Zeugnisreports werden regelmäßig über die Webseite des MSB für Schulverwaltungssoftware bereitgestellt.</p>",5),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Die angelegten Einträge können dauerhaft bestehen bleiben. Zu jedem Abschnittsende, an dem Zeugnisse, Leistungsübersichten oder ähnliche Reports gedruckt werden, sollte jedoch geprüft werden, ob eine aktuellere Vorlage zugeordnet werden muss.")],-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis – Siehe auch")]),e("ul",null,[e("li",null,[e("a",{href:"/reporting/zeugnisformulare/zeugnisformulare-herunterladen-und-aktualisieren.html"},"Zeugnisformulare herunterladen und bereitstellen")]),e("li",null,[e("a",{href:"/reporting/zeugnisformulare/zeugnisse-themenuebersicht.html"},"Den Zeugnisdruck vorbereiten")])])],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Zeugnisvorlagen_zuordnen_(Schulbezogene_Kataloge)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 6867.")],-1)])])}const k=s(u,[["render",g]]);export{f as __pageData,k as default};
